"""Conservative, review-only annotation proposals generated by Mode 0."""
from __future__ import annotations

from dataclasses import asdict
import hashlib
import json
from typing import Any

import numpy as np
import pandas as pd

from .metadata import utc_now_iso
from .rep_detection import RepDetector


SUGGESTION_SCHEMA_VERSION = "1.0"
SUGGESTION_STATES = {"pending", "accepted", "edited", "rejected"}


def update_suggestion_review(
    document: dict[str, Any],
    suggestion_id: str,
    status: str,
    *,
    final_boundaries: dict[str, Any] | None = None,
    accepted_annotation_id: str | None = None,
) -> dict[str, Any]:
    """Return a reviewed copy while preserving original proposal boundaries."""
    if status not in SUGGESTION_STATES:
        raise ValueError(f"Unsupported suggestion review status: {status}")
    updated = json.loads(json.dumps(document))
    target = next(
        (item for item in updated.get("suggestions", []) if item.get("suggestion_id") == suggestion_id),
        None,
    )
    if target is None:
        raise KeyError(f"Unknown suggestion_id: {suggestion_id}")
    target["review_status"] = status
    target["reviewed_at"] = utc_now_iso()
    target["final_user_boundaries"] = dict(final_boundaries) if final_boundaries is not None else None
    target["accepted_annotation_id"] = accepted_annotation_id
    return updated


def _stable_id(payload: dict[str, Any]) -> str:
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
    return "AS-" + hashlib.sha256(encoded).hexdigest()[:16]


def _segments(mask: np.ndarray, timestamps: np.ndarray, *, minimum_s: float) -> list[tuple[int, int]]:
    indices = np.flatnonzero(mask)
    if not len(indices):
        return []
    breaks = np.flatnonzero(np.diff(indices) > 1)
    starts = np.r_[indices[0], indices[breaks + 1]]
    ends = np.r_[indices[breaks], indices[-1]]
    return [
        (int(start), int(end)) for start, end in zip(starts, ends)
        if timestamps[end] - timestamps[start] >= minimum_s
    ]


def _merge_ranges(ranges: list[tuple[int, int]], timestamps: np.ndarray, maximum_gap_s: float) -> list[tuple[int, int]]:
    merged: list[tuple[int, int]] = []
    for start, end in ranges:
        if merged and timestamps[start] - timestamps[merged[-1][1]] <= maximum_gap_s:
            merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))
    return merged


def _proposal(
    *,
    layer: str,
    label: str,
    start_index: int,
    end_index: int,
    frame_ids: np.ndarray,
    timestamps: np.ndarray,
    confidence: float,
    method: str,
    parameters: dict[str, Any],
    supporting_features: list[str],
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    boundaries = {
        "start_frame": int(frame_ids[start_index]),
        "end_frame": int(frame_ids[end_index]),
        "start_time_s": float(timestamps[start_index]),
        "end_time_s": float(timestamps[end_index]),
    }
    identity = {"layer": layer, "label": label, **boundaries, "method": method}
    return {
        "suggestion_id": _stable_id(identity),
        "annotation_layer": layer,
        "suggested_label": label,
        **boundaries,
        "confidence": float(np.clip(confidence, 0.0, 1.0)),
        "detection_method": method,
        "parameters": parameters,
        "supporting_features": supporting_features,
        "review_status": "pending",
        "original_proposed_boundaries": dict(boundaries),
        "final_user_boundaries": None,
        **(extra or {}),
    }


def _motion_score(df: pd.DataFrame, timestamps: np.ndarray) -> tuple[np.ndarray, list[str]]:
    candidates = [
        column for column in df.columns
        if column.startswith("angle_")
        and not column.startswith(("angle_2d_", "angle_3d_", "angle_torso2d_"))
    ][:16]
    candidates += [
        column for landmark in (11, 12, 15, 16, 23, 24, 25, 26, 27, 28)
        for column in (f"lm{landmark}_x", f"lm{landmark}_y") if column in df.columns
    ]
    dt = np.r_[np.nan, np.diff(timestamps)]
    signals = []
    used = []
    for column in dict.fromkeys(candidates):
        values = pd.to_numeric(df[column], errors="coerce").to_numpy(dtype=float)
        derivative = np.abs(np.r_[np.nan, np.diff(values)] / dt)
        finite = derivative[np.isfinite(derivative)]
        if len(finite) < 8:
            continue
        scale = float(np.median(np.abs(finite - np.median(finite)))) * 1.4826
        if scale <= 1e-9:
            low, high = np.percentile(finite, [10, 90])
            scale = float(high - low)
        if scale <= 1e-9:
            continue
        signals.append(np.nan_to_num(np.clip(derivative / scale, 0.0, 25.0), nan=0.0))
        used.append(column)
    if not signals:
        return np.zeros(len(df), dtype=float), []
    score = np.nanmedian(np.column_stack(signals), axis=1)
    median_dt = float(np.nanmedian(np.diff(timestamps))) if len(timestamps) > 1 else 1 / 30.0
    window = max(3, int(round(0.75 / max(median_dt, 1e-9))))
    score = pd.Series(score).rolling(window, center=True, min_periods=1).median().to_numpy(dtype=float)
    return np.nan_to_num(score, nan=0.0), used


def generate_annotation_suggestions(
    df: pd.DataFrame,
    *,
    config: dict[str, Any] | None = None,
    tracking_quality: dict[str, Any] | None = None,
    exercise_hint: str | None = None,
    processing_version: str | None = None,
) -> dict[str, Any]:
    config = config or {}
    if df.empty:
        return {
            "schema_version": SUGGESTION_SCHEMA_VERSION,
            "authoritative_source": "annotations.json",
            "suggestions": [],
            "diagnostics": {"abstentions": ["empty feature table"]},
        }
    timestamps = pd.to_numeric(df["timestamp_s"], errors="coerce").to_numpy(dtype=float)
    frame_ids = pd.to_numeric(df["frame_id"], errors="coerce").astype(int).to_numpy()
    pose_present = pd.to_numeric(
        df.get("pose_present", pd.Series(1, index=df.index)), errors="coerce"
    ).fillna(0).to_numpy() > 0
    score, supporting = _motion_score(df, timestamps)
    finite_score = score[np.isfinite(score) & pose_present]
    suggestions: list[dict[str, Any]] = []
    abstentions: list[str] = []
    parameters = {
        "activity_minimum_s": 0.75,
        "activity_merge_gap_s": 0.50,
        "set_merge_gap_s": 0.0,
        "timestamp_based": True,
    }
    active_ranges: list[tuple[int, int]] = []
    if finite_score.size >= 8 and float(np.nanmax(finite_score) - np.nanmin(finite_score)) > 1e-6:
        high = float(np.nanquantile(finite_score, 0.65))
        active_mask = pose_present & (score >= max(high, 0.75))
        active_ranges = _merge_ranges(
            _segments(active_mask, timestamps, minimum_s=0.0),
            timestamps,
            parameters["activity_merge_gap_s"],
        )
        active_ranges = [
            (start, end) for start, end in active_ranges
            if timestamps[end] - timestamps[start] >= parameters["activity_minimum_s"]
        ]
        for start, end in active_ranges:
            confidence = 0.55 + 0.30 * min(1.0, float(np.nanmedian(score[start:end + 1])) / max(high * 2, 1e-9))
            suggestions.append(_proposal(
                layer="activity_state", label="active", start_index=start, end_index=end,
                frame_ids=frame_ids, timestamps=timestamps, confidence=confidence,
                method="multiscale_motion_activity_v1", parameters=parameters,
                supporting_features=supporting,
                extra={"exercise_hint": exercise_hint},
            ))
    else:
        abstentions.append("Activity suggestion abstained: insufficient varying motion evidence; static activity may require human review.")

    # The current annotation contract requires every set to be contained in a
    # proposed active interval. Keep identical boundaries until broader active
    # grouping across rest pauses has been validated.
    set_ranges = list(active_ranges)
    for set_number, (start, end) in enumerate(set_ranges, start=1):
        suggestions.append(_proposal(
            layer="set", label=f"set_{set_number}", start_index=start, end_index=end,
            frame_ids=frame_ids, timestamps=timestamps, confidence=0.58,
            method="grouped_activity_set_v1", parameters=parameters,
            supporting_features=supporting,
            extra={"set_id": set_number, "exercise_hint": exercise_hint},
        ))

    detector = RepDetector.from_config(config)
    rep_number_by_set: dict[int, int] = {}
    for start, end in active_ranges:
        segment = df.iloc[start:end + 1].copy()
        segment["activity_state_label"] = "active"
        detection = detector.detect_segment(segment, activity_state="active")
        containing_set = next(
            (number for number, (set_start, set_end) in enumerate(set_ranges, start=1)
             if set_start <= start and end <= set_end),
            1,
        )
        for candidate in detection.candidates:
            candidate_start = int(np.searchsorted(frame_ids, candidate.start_frame, side="left"))
            candidate_end = int(np.searchsorted(frame_ids, candidate.end_frame, side="right") - 1)
            candidate_start = max(0, min(len(df) - 1, candidate_start))
            candidate_end = max(candidate_start, min(len(df) - 1, candidate_end))
            rep_number_by_set[containing_set] = rep_number_by_set.get(containing_set, 0) + 1
            rep_id = rep_number_by_set[containing_set]
            suggestions.append(_proposal(
                layer="rep", label=f"rep_{rep_id}", start_index=candidate_start,
                end_index=candidate_end, frame_ids=frame_ids, timestamps=timestamps,
                confidence=candidate.confidence, method="periodic_motion_rep_v1",
                parameters=asdict(detector.config), supporting_features=[candidate.signal_name],
                extra={"set_id": containing_set, "rep_id": rep_id},
            ))

    phase_definitions = config.get("annotation_suggestions", {}).get("phase_definitions", {})
    if exercise_hint and exercise_hint in phase_definitions:
        abstentions.append("Configured phase definitions are present but automatic phase proposal remains disabled until exercise-specific validation is complete.")
    else:
        abstentions.append("Phase suggestion abstained: no validated exercise-specific phase definition.")
    abstentions.append("Form suggestion abstained: tracking anomalies are stored as quality warnings, not form errors.")

    return {
        "schema_version": SUGGESTION_SCHEMA_VERSION,
        "generated_at": utc_now_iso(),
        "source": "Mode 0 derived annotation suggestions",
        "authoritative_source": "annotations.json",
        "processing_version": processing_version,
        "exercise_hint": exercise_hint,
        "supported_review_states": sorted(SUGGESTION_STATES),
        "suggestions": sorted(
            suggestions,
            key=lambda item: (item["start_time_s"], item["end_time_s"], item["annotation_layer"]),
        ),
        "tracking_quality_reference": {
            "warning_count": len((tracking_quality or {}).get("warnings", [])),
            "classified_as_form_errors": False,
        },
        "diagnostics": {
            "motion_features": supporting,
            "activity_range_count": len(active_ranges),
            "set_range_count": len(set_ranges),
            "abstentions": abstentions,
        },
    }

